import {language} from './ui.mjs';
const tweet='https://x.com/Fillout_rh/status/2110667258846449820';
const postText='A few parts, a few wires, a whole lot of possibilities. Exploring FillOut, where logic becomes something you can build, connect and bring to life. Curious to see what comes next.\n\n@Fillout_rh';
const composeUrl=()=>'https://x.com/intent/post?text='+encodeURIComponent(language==='zh'?'几个元件，几根连线，无限的可能。我正在探索 FillOut，把逻辑变成可以亲手构建、连接并点亮的电路。期待接下来的新进展。\n\n@Fillout_rh':postText);
let manualAddress='';try{manualAddress=localStorage.getItem('fillout-quest-evm')||'';}catch{}
const state={follow:{opened:false,status:'idle'},engage:{opened:false,status:'idle'},post:{url:'',status:'idle'}};
export function validTweetLink(raw){try{const u=new URL(raw);return u.protocol==='https:'&&['x.com','www.x.com','twitter.com','www.twitter.com'].includes(u.hostname)&&/^\/[A-Za-z0-9_]{1,15}\/status\/\d+\/?$/.test(u.pathname)?u.origin+u.pathname:null;}catch{return null;}}
export function mountQuestTasks(app){
app.innerHTML=`<div class="local-heading quest-heading"><p class="eyebrow">FILLOUT / QUESTS</p><h1>MAKE SOME NOISE.<span>✳</span></h1><p>Three social tasks for whitelist consideration.</p></div><dialog class="quest-address-dialog" aria-labelledby="quest-address-title"><button type="button" class="quest-address-close" aria-label="Close address form">×</button><section class="quest-evm-panel"><div><h2 id="quest-address-title">Add your EVM address</h2><p>Connect a wallet or enter the EVM address you want to use for whitelist consideration.</p></div><form class="quest-evm-form"><label for="quest-evm-address">EVM address</label><div class="quest-evm-input-row"><input id="quest-evm-address" name="evm-address" type="text" placeholder="0x…" maxlength="42" required autocomplete="off" spellcheck="false"><button type="submit">Save address</button></div><p class="quest-evm-status" role="status" aria-live="polite"></p></form></section></dialog><div class="quest-task-list"><article class="quest-task" data-task="follow"><span class="quest-task-number">01</span><div class="quest-task-copy"><h2>Follow FillOut</h2><p>Follow <strong>@Fillout_rh</strong> on X.</p><div class="quest-task-actions"><a href="https://x.com/Fillout_rh" target="_blank" rel="noopener noreferrer" data-open="follow">Follow on X ↗</a><button data-verify="follow">Verify</button></div><p data-status="follow" class="task-status" aria-live="polite"></p></div></article><article class="quest-task" data-task="engage"><span class="quest-task-number">02</span><div class="quest-task-copy"><h2>Like & repost</h2><p>Like and repost the official FillOut post.</p><div class="quest-task-actions"><a href="${tweet}" target="_blank" rel="noopener noreferrer" data-open="engage">Open post ↗</a><button data-verify="engage">Verify</button></div><p data-status="engage" class="task-status" aria-live="polite"></p></div></article><article class="quest-task" data-task="post"><span class="quest-task-number">03</span><div class="quest-task-copy"><h2>Your take on FillOut</h2><p>Write about FillOut on X. Personalize the suggested text with your own thoughts and mention <strong>@Fillout_rh</strong>, then add your post link.</p><div class="quest-task-actions"><a href="${composeUrl()}" target="_blank" rel="noopener noreferrer">Write on X ↗</a><button data-add-link>Add your post</button></div><form class="quest-post-form" hidden><label for="quest-post-link">Your post link</label><input id="quest-post-link" type="url" required placeholder="https://x.com/yourname/status/…" autocomplete="off"><p class="post-verification-rules">Posts are reviewed manually. Deleted posts are not valid. X API checks may be added later.</p><div class="quest-task-actions"><button type="submit">Verify</button></div></form><p data-status="post" class="task-status" aria-live="polite"></p></div></article></div><a class="quests-back-home" href="#home"><svg viewBox="0 0 32 28" aria-hidden="true"><path class="return-simple-arrow" d="M14 4H9v5H4v5h5v5h5v-5h10v9h5V9H14z"/></svg><span>Back to home</span></a><p class="quest-verification-note">Whitelist eligibility requires manual review. Deleted or unavailable posts are excluded. Social activity will be checked again before the whitelist is finalized.</p>`;
const $=s=>app.querySelector(s);
$('#quest-evm-address').value=manualAddress;$('.quest-address-close').onclick=()=>$('.quest-address-dialog').close();
if(new URLSearchParams(location.search).get('demo')==='address')queueMicrotask(()=>{if(app.isConnected&&document.body.dataset.page==='quests')$('.quest-address-dialog').showModal();});
$('.quest-evm-form').onsubmit=async event=>{event.preventDefault();const raw=$('#quest-evm-address').value.trim(),status=$('.quest-evm-status'),save=$('.quest-evm-form button[type=submit]');save.disabled=true;try{const {getAddress}=await import('./ethers.mjs');let normalized;try{normalized=getAddress(raw);if(/^0x0{40}$/i.test(normalized))throw Error();}catch{status.textContent='Enter a valid EVM address.';return;}if(!state.post.url){status.textContent='Add your post link first.';return;}status.textContent='Saving your submission…';const session=await fetch('/api/quests/session',{method:'POST',credentials:'same-origin'});if(!session.ok)throw Error('Submission service is unavailable. Please try again later.');const response=await fetch('/api/quests/submissions',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({address:normalized,postUrl:state.post.url,followAttested:state.follow.opened,repostAttested:state.engage.opened})});const value=await response.json();if(!response.ok||value.received!==true)throw Error(value.error||'Your submission could not be saved.');manualAddress=normalized;try{localStorage.setItem('fillout-quest-evm',normalized);}catch{}$('.quest-address-dialog').close();showAddressSaved(value.id);}catch(error){status.textContent=error.message||'Submission service unavailable. Please try again.';}finally{save.disabled=false;}};

function showAddressSaved(id){let note=app.querySelector('.quest-address-saved');if(!note){note=document.createElement('p');note.className='quest-address-saved';note.setAttribute('role','status');app.querySelector('.quest-task-list').after(note);}note.textContent='Submission received: '+id+'. Whitelist eligibility is subject to manual review.';}
function refresh(id){const t=state[id],status=$('[data-status="'+id+'"]'),button=$('[data-verify="'+id+'"]');if(!status)return;if(t.status==='checking'){status.textContent='Checking…';status.className='task-status is-checking';}else if(t.status==='pending'){status.textContent='';status.className='task-status is-pending';}else if(t.status==='verified'){status.textContent='Post verified';status.className='task-status is-verified';}else{status.textContent='';status.className='task-status';}if(button){button.disabled=!t.opened||t.status==='checking';button.textContent=t.status==='checking'?'Checking…':'Verify';}}
async function check(id){const task=state[id];if(task.status==='checking')return;task.status='checking';refresh(id);const submit=$('.quest-post-form button[type=submit]');if(id==='post')submit.disabled=true;await new Promise(resolve=>setTimeout(resolve,7500));task.status='pending';if(app.querySelector('[data-task="'+id+'"]')){refresh(id);if(id==='post')submit.disabled=false;}}
app.querySelectorAll('[data-open]').forEach(link=>link.addEventListener('click',()=>{state[link.dataset.open].opened=true;state[link.dataset.open].status='idle';refresh(link.dataset.open);}));app.querySelectorAll('[data-verify]').forEach(button=>button.onclick=()=>{if(state[button.dataset.verify].opened)void check(button.dataset.verify);});
$('[data-add-link]').onclick=()=>{const form=$('.quest-post-form');form.hidden=!form.hidden;if(!form.hidden)$('#quest-post-link').focus();};$('.quest-post-form').onsubmit=e=>{e.preventDefault();const raw=$('#quest-post-link').value.trim(),url=validTweetLink(raw);if(!url){$('[data-status="post"]').textContent='Enter a valid X post link.';return;}if(url.includes('/Fillout_rh/status/2110667258846449820')){$('[data-status="post"]').textContent='Add your own original post, not the official post.';return;}if(state.follow.status!=='pending'&&state.follow.status!=='verified'||state.engage.status!=='pending'&&state.engage.status!=='verified'){$('[data-status="post"]').textContent='Complete the first two task checks before adding your address.';return;}state.post.url=url;$('.quest-address-dialog').showModal();const status=$('[data-status="post"]'),submit=$('.quest-post-form button[type=submit]');submit.disabled=true;status.textContent='Checking the post…';status.className='task-status is-checking';
(async()=>{try{const response=await fetch('/api/quests/verify-post',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({url}),signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('unavailable');const result=await response.json();if(result?.verified!==true||result?.checks?.exists!==true||result?.checks?.notDeleted!==true||result?.checks?.manualApproved!==true||result?.checks?.mentionsFillOut!==true||result?.checks?.authorMatchesConnectedX!==true||result?.checks?.originalPost!==true||result?.checks?.campaignEligible!==true||result?.url!==url){status.textContent='This post could not be verified. Use your own original FillOut post.';return;}state.post.url=url;state.post.status='verified';status.textContent='Post verified';status.className='task-status is-verified';}catch{status.textContent='Verification could not be completed. Please try again.';status.className='task-status';}finally{submit.disabled=false;}})();};$('#quest-post-link').value=state.post.url;for(const id of Object.keys(state)){if(state[id].status==='checking')state[id].status='idle';refresh(id);}
}
